#!/bin/bash
# Re-apply a gk6ctl onboard layer at login.
# Generated by install-launchagent.sh (paths below are substituted at install time).
set -u

GK6CTL="%%GK6CTL%%"
PROFILE="%%PROFILE%%"
LOG="%%LOG%%"
ATTEMPTS=10

log() { echo "$(date '+%Y-%m-%d %H:%M:%S') $*" >> "$LOG"; }

# Wait a short while for the keyboard to enumerate (it's USB-powered, so at
# login it's usually already there; this covers slow hubs/wakes).
for i in $(seq 1 "$ATTEMPTS"); do
    if "$GK6CTL" status >/dev/null 2>&1; then
        break
    fi
    if [ "$i" = "$ATTEMPTS" ]; then
        log "keyboard not detected after ${ATTEMPTS}s — SKIP"
        exit 0
    fi
    sleep 1
done

"$GK6CTL" ensure "$PROFILE" >> "$LOG" 2>&1
rc=$?
if [ "$rc" -eq 0 ]; then
    log "layer ensured ($PROFILE)"
else
    log "ensure failed (exit $rc)"
fi
exit 0